import json, pathlib, struct, zlib
m=json.load(open('manifest.json'))['items']; s=json.load(open('submission.json'))['items']; runs=json.load(open('media.json'))['runs']; assert len(m)==len(s)==len(runs)==11
for i,(a,b,r) in enumerate(zip(m,s,runs),1):
 assert a['request_id']==b['request_id']==r['request_id'] and b['run_id']==r['run_id'] and r['status']=='succeeded' and len(r['images'])==1
 assert r['parameters']['positive_prompt']==pathlib.Path(a['parameter_files']['positive_prompt']).read_text() and r['parameters']['seed']==424241+i
 p=pathlib.Path(r['images'][0]['file_path']); data=p.read_bytes(); assert data[:8]==b'\x89PNG\r\n\x1a\n'; pos=8; chunks=[]; dims=None; end=False
 while pos<len(data):
  n=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8]; body=data[pos+8:pos+8+n]; crc=struct.unpack('>I',data[pos+8+n:pos+12+n])[0]; assert zlib.crc32(typ+body)&0xffffffff==crc
  if typ==b'IHDR': dims=struct.unpack('>II',body[:8])
  if typ==b'IDAT': chunks.append(body)
  pos+=12+n
  if typ==b'IEND': end=True; break
 assert end and dims==(512,512) and zlib.decompress(b''.join(chunks)) and pos==len(data)
 print(f'{i:02} {r["run_id"]} {p} OK {dims}')
PY"}

